const climate = (flow.get("timechart.climateschedule") || []).map(p => item(p.fromtime, p.totime,
    "T " + p.tempmin + "-" + p.tempmax + " °C, RH " + p.hummin + "-" + p.hummax + " %"));
return { "payload": { "lanes": [
